scwin.grid1_groupbyFilterBoxFormatter = function(data, isGroupby) {
    //	debugger;
    console.log(data);
    var label = "";
    var labelArr = [];
    var groupbyStr = isGroupby ? "(groupby)" : "";
    if (data.length === 0) {
        return "-all-";
    }
    for (var i = 0; i < data.length; i++) {
        var s_label = "";
        var obj = data[i];
        var header = obj.header;
        var filter = obj.filter;
        if (filter[0].values.length === 0) {
            debugger;
            label = data[0].header + " " + data[0].filter[0].operator + " -null-";
        } else {
            for (var j = 0; j < filter.length; j++) {
                if (filter[j].gate)
                    s_label = s_label + " " + filter[j].gate + " ";
                var values = filter[j].values;
                if (values.join)
                    values = "[" + values.join(" ,") + "]";
                s_label = s_label + filter[j].operator + " " + values;
            }
            s_label = "(" + header + " " + s_label + ")";
            labelArr.push(s_label);
            label = groupbyStr + labelArr.join(" & ");
        }
    }
    return label;
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '금액'항목의 필터(역삼각형)를 클릭한다.
    //1. After running the sample, click the filter (inverted triangle) in the 'Amount' item.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_header4_filter').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. '금액'항목의 filterList가 보여진다.
    //1. The filterList of the 'Amount' item is displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_customFilter_scrollView').is(':visible')", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step 2. ''1값을 클릭하여 체크해지한다.
    //2. Click the ''1 value to cancel the check.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. ''1값이 제외되고 필터링이 수행된다.
    //2. The ''1 value is excluded and filtering is performed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].checked == false", "true");
    //Test step 3. 마우스로 다른곳을 클릭하고 ctrl+마우스 우클릭 > 로그보기에서 정상로그를 확인한다.
    //3. Click elsewhere with your mouse and check the normal log in ctrl + right-click> log view.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_header4_filter').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "WebSquare.logger.getErrorLog() == ''", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
